insert(i,text) { checkInsertRange(i); [a,b]=split(root,i);
 middle=buildBalancedBoundedChunks(text);
 candidate=join(join(a,middle),b); assertWeightsAndAvl(candidate);
 publish(candidate); }
deleteRange(i,m) { checkRange(i,m); [a,tail]=split(root,i);
 [removed,b]=split(tail,m); publish(join(a,b)); retire(removed); }
read(i) { checkReadRange(i); n=root; while(!n.leaf) {
 if(i<n.left.count)n=n.left; else {i-=n.left.count; n=n.right;} }
 return scalarAt(n.chunk,i); }

count(n)=n?count(n.left)+n.chunk.scalarCount+count(n.right):0;
merge(a,b) { if(!a)return b; if(!b)return a;
 if(priority(a)<priority(b)) return copy(a,{right:merge(a.right,b)},recomputeCount);
 return copy(b,{left:merge(a,b.left)},recomputeCount); }
insert(i,s) { [a,b]=splitByCount(root,i); publish(merge(merge(a,buildChunks(s)),b)); }
deleteRange(i,m) { [a,t]=splitByCount(root,i); [gone,b]=splitByCount(t,m);
 publish(merge(a,b)); retire(gone); }
